const exists = s.hypotheses.find(h => h.id === 'hyp-df6fac7f');
if (!exists) {
  s.hypotheses.push({
    id: 'hyp-df6fac7f',
    description: 'In lib/index.js, the toVal function (line 5) mishandles a boolean val when the key is registered as boolean. The expression out._.push((x = +val, x * 0 === 0) ? x : val) coerces the boolean true to the number 1 via +true and pushes it into out._. The bug surfaces when (a) the user declares a boolean default (default: { foo: true }) which causes opts.boolean.push(key) at lines 40-44, and (b) the flag is supplied without a value (e.g., --foo at end-of-args), causing val to be the literal boolean true. Result: out._ gets a numeric entry instead of being empty. The boolean branch should treat an already-boolean val as a boolean and not push it to out._.',
    evidence: ['lib/index.js:5 boolean branch pushes +val', 'lib/index.js:88 parser sets val=true when end-of-args', 'lib/index.js:42 default registration pushes key to opts.boolean when typeof default[key]===boolean', 'Repro: mri([--foo], {boolean:foo, default:{foo:true}}) -> {foo:true, _:[1]}'],
    confidence: 0.95,
    status: 'selected',
    files: ['lib/index.js']
  });
  s.selectedHypothesis = 'hyp-df6fac7f';
  fs.writeFileSync('.v1/state.json', JSON.stringify(s, null, 2));
  console.log('added');
} else {
  console.log('already exists');
}
console.log('count:', s.hypotheses.length);
