const fs = require('fs');
const s = JSON.parse(fs.readFileSync('.v1/state.json', 'utf-8'));
s.hypotheses = s.hypotheses || [];
// ensure unique by id
const target = {
  id: 'hyp-df6fac7f',
  description: 'In lib/index.js, the toVal function mishandles a boolean val for boolean-typed keys. The boolean branch expression out._.push((x = +val, x * 0 === 0) ? x : val) coerces the boolean true (val===true) into the number 1 via +true and pushes it into out._. Bug surfaces when: (a) the user declares a boolean default (default: { foo: true }) which causes opts[typeof opts.default[k]].push(k) at line ~42 to register the key in opts.boolean; and (b) the flag is supplied without a value (e.g., --foo at end-of-args, or as an intermediate character in a cluster like -ab), causing the parser at line ~88 to set val = the literal boolean true. Result: out._ gets a numeric entry (1) instead of being empty. The boolean branch should treat an already-boolean val as a boolean and not push it to out._.',
  evidence: [
    'lib/index.js:5 - boolean branch uses out._.push((x = +val, ...)) which coerces booleans to numbers',
    'lib/index.js:42 - default registration: opts[typeof opts.default[k]] .push(k) places boolean-default keys into opts.boolean',
    'lib/index.js:88 - parser: val = arg.substring(++idx) || (i+1 === len || ...charCodeAt(0)===45 || args[++i]) sets val=true when end-of-args',
    'Reproduction: mri([--foo], {boolean:foo, default:{foo:true}}) returned {foo:true, _:[1]} before the fix'
  ],
  confidence: 0.95,
  status: 'selected',
  files: ['lib/index.js']
};
if (!s.hypotheses.find(h => h.id === target.id)) {
  s.hypotheses.push(target);
}
s.selectedHypothesis = target.id;
s.phase = 'diagnosis';
fs.writeFileSync('.v1/state.json', JSON.stringify(s, null, 2));
// verify
const re = JSON.parse(fs.readFileSync('.v1/state.json', 'utf-8'));
console.log('hypotheses count:', re.hypotheses.length);
console.log('selected:', re.selectedHypothesis);
console.log('phase:', re.phase);
console.log('desc:', re.hypotheses[0].description.substring(0, 120) + '...');
"
